INSERT INTO lessons (id,sub_strand_id,title,estimated_minutes,status,published_at,source_id) VALUES ('l-g5m-1-6-1','g5m-1-6','Equivalent Fractions and Simplifying',25,'published',datetime('now'),'src-smartlearn-pilot');
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-1-s1','l-g5m-1-6-1','introduction','A chapati to share','{"text":"Wanjiru cuts a chapati into 2 equal pieces and eats 1. Her brother cuts an identical chapati into 4 equal pieces and eats 2. Who ate more? Let us find out.","visual":{"type":"fraction_bars","items":[[1,2],[2,4]]}}',1);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-1-s2','l-g5m-1-6-1','outcomes','By the end of this lesson','{"bullets":["Recognise equivalent fractions","Make equivalent fractions by multiplying or dividing","Simplify a fraction to its simplest form"]}',2);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-1-s3','l-g5m-1-6-1','explanation','Same amount, different numbers','{"text":"Equivalent fractions name the same amount using different numbers. Look at the bars: each one is the same length and the same part is shaded, so 1/2, 2/4 and 4/8 are equal.","visual":{"type":"fraction_bars","items":[[1,2],[2,4],[4,8]]},"bullets":["To make an equivalent fraction, multiply the top and the bottom by the same number.","1/2 = 2/4 = 4/8 (multiplying by 2 each time)","To simplify, divide the top and the bottom by a number that goes into both."],"callout":"Whatever you do to the bottom number, do the same to the top number."}',3);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-1-s4','l-g5m-1-6-1','example','Worked example: simplify 6/8','{"steps":["Find a number that divides both 6 and 8 exactly. It is 2.","6 ÷ 2 = 3 and 8 ÷ 2 = 4.","So 6/8 = 3/4.","Only 1 divides both 3 and 4, so 3/4 is in its simplest form."],"visual":{"type":"fraction_bars","items":[[6,8],[3,4]]}}',4);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-1-s5','l-g5m-1-6-1','activity','Try it at home','{"steps":["Fold a sheet of paper in half and shade 1 part.","Fold it again so there are 4 parts. How many parts are shaded now?","Fold once more to get 8 parts. Write the fraction each time.","What do you notice about the three fractions?"]}',5);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-1-s6','l-g5m-1-6-1','practice','Check your understanding','{"qa":[{"q":"Write two fractions equivalent to 1/3.","a":"For example 2/6 and 3/9 (multiply top and bottom by 2 or by 3)."},{"q":"Simplify 10/15.","a":"Divide top and bottom by 5 to get 2/3."},{"q":"Is 3/9 equal to 1/3?","a":"Yes. Divide the top and bottom of 3/9 by 3 to get 1/3."}]}',6);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-1-s7','l-g5m-1-6-1','reflection','Think about it','{"text":"Where at home do you share something into equal parts, like a mandazi or a loaf? How would you explain to a friend that 2/4 and 1/2 are the same?"}',7);
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5m-1-6-1','g5m-1-6-o1');
INSERT INTO lessons (id,sub_strand_id,title,estimated_minutes,status,published_at,source_id) VALUES ('l-g5m-1-6-2','g5m-1-6','Comparing and Ordering Fractions',25,'published',datetime('now'),'src-smartlearn-pilot');
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-2-s1','l-g5m-1-6-2','introduction','Who drank more?','{"text":"Kamau drinks 3/4 of a bottle of juice. Achieng drinks 5/8 of an identical bottle. Who drank more?","visual":{"type":"fraction_bars","items":[[3,4],[5,8]]}}',1);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-2-s2','l-g5m-1-6-2','outcomes','By the end of this lesson','{"bullets":["Compare fractions with the same denominator","Compare fractions with different denominators","Order fractions from smallest to largest"]}',2);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-2-s3','l-g5m-1-6-2','explanation','Comparing fractions','{"text":"When the denominators are the same, the pieces are the same size, so the bigger numerator means the bigger fraction. When the denominators are different, change the fractions so they have the same denominator, then compare.","bullets":["Same denominator: 3/8 is less than 5/8.","Different denominators: find a number both denominators go into, and make equivalent fractions."],"callout":"Compare like with like: first make the pieces the same size."}',3);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-2-s4','l-g5m-1-6-2','example','Worked example: 3/4 or 5/8?','{"steps":["4 goes into 8, so use 8 as the common denominator.","3/4 = 6/8 (multiply top and bottom by 2).","Compare 6/8 and 5/8. 6 is more than 5.","So 3/4 is greater than 5/8. Kamau drank more."],"visual":{"type":"fraction_bars","items":[[6,8],[5,8]]}}',4);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-2-s5','l-g5m-1-6-2','example','Worked example: ordering','{"steps":["Order 1/2, 1/3 and 1/6 from smallest to largest.","The common denominator is 6.","1/2 = 3/6, 1/3 = 2/6 and 1/6 = 1/6.","From smallest to largest: 1/6, 1/3, 1/2."],"visual":{"type":"fraction_bars","items":[[1,6],[2,6],[3,6]]}}',5);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-2-s6','l-g5m-1-6-2','activity','Fraction cards','{"steps":["Write 1/2, 1/3, 1/4, 1/6, 2/3 and 3/4 on small pieces of paper.","Shuffle them and pick two cards.","Use paper strips or drawings to decide which fraction is bigger.","Put all six cards in order from smallest to largest."]}',6);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-2-s7','l-g5m-1-6-2','practice','Check your understanding','{"qa":[{"q":"Which is greater, 5/6 or 2/3?","a":"2/3 = 4/6, so 5/6 is greater."},{"q":"Order 1/4, 3/4 and 1/2 from smallest to largest.","a":"1/4, 1/2, 3/4."},{"q":"Which is smaller, 3/5 or 7/10?","a":"3/5 = 6/10, so 3/5 is smaller."}]}',7);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-2-s8','l-g5m-1-6-2','reflection','Think about it','{"text":"When you share food, why does it help to cut pieces of the same size?"}',8);
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5m-1-6-2','g5m-1-6-o2');
INSERT INTO lessons (id,sub_strand_id,title,estimated_minutes,status,published_at,source_id) VALUES ('l-g5m-1-6-3','g5m-1-6','Adding and Subtracting Fractions',30,'published',datetime('now'),'src-smartlearn-pilot');
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-3-s1','l-g5m-1-6-3','introduction','A bag of flour','{"text":"A mother uses 2/8 of a bag of flour on Monday and 3/8 on Tuesday. What fraction of the bag did she use in all?","visual":{"type":"fraction_bars","items":[[2,8],[3,8],[5,8]]}}',1);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-3-s2','l-g5m-1-6-3','outcomes','By the end of this lesson','{"bullets":["Add fractions with the same denominator","Subtract fractions with the same denominator","Add and subtract when one fraction needs renaming"]}',2);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-3-s3','l-g5m-1-6-3','explanation','Keep the pieces the same size','{"text":"When the denominators are the same, add or subtract only the numerators. The denominator stays the same because the size of the pieces does not change.","bullets":["2/8 + 3/8 = 5/8","5/8 − 2/8 = 3/8"],"callout":"The denominator tells the size of the pieces. It stays the same."}',3);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-3-s4','l-g5m-1-6-3','example','Worked example: renaming one fraction','{"steps":["Work out 1/2 + 1/4.","Rename 1/2 as quarters: 1/2 = 2/4.","Now add: 2/4 + 1/4 = 3/4.","Subtraction works the same way: 3/4 − 1/2 = 3/4 − 2/4 = 1/4."],"visual":{"type":"fraction_bars","items":[[2,4],[1,4],[3,4]]}}',4);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-3-s5','l-g5m-1-6-3','activity','Bean fractions','{"steps":["Take 8 beans. Each bean is 1/8 of the group.","Push 2 beans to one side and 3 beans to the other.","Join them. How many eighths do you have?","Take away 4 beans. What fraction is left?"]}',5);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-3-s6','l-g5m-1-6-3','practice','Check your understanding','{"qa":[{"q":"3/10 + 4/10 = ?","a":"7/10"},{"q":"7/9 − 2/9 = ?","a":"5/9"},{"q":"1/2 + 1/6 = ?","a":"1/2 = 3/6, so 3/6 + 1/6 = 4/6, which simplifies to 2/3."}]}',6);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-6-3-s7','l-g5m-1-6-3','reflection','Think about it','{"text":"Why can we not just add the denominators when we add fractions?"}',7);
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5m-1-6-3','g5m-1-6-o3');
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5m-1-6-3','g5m-1-6-o4');
INSERT INTO lessons (id,sub_strand_id,title,estimated_minutes,status,published_at,source_id) VALUES ('l-g5m-1-1-1','g5m-1-1','Place Value, Rounding and Divisibility',30,'published',datetime('now'),'src-smartlearn-pilot');
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-1-1-s1','l-g5m-1-1-1','introduction','A school fundraiser','{"text":"A school fundraiser raised KES 365,482. Each digit in that number has a job. What does the 6 stand for?"}',1);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-1-1-s2','l-g5m-1-1-1','outcomes','By the end of this lesson','{"bullets":["Find the place value and total value of digits","Round numbers to the nearest hundred and thousand","Use divisibility tests for 2, 5 and 10"]}',2);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-1-1-s3','l-g5m-1-1-1','explanation','Place value and total value','{"text":"Place value is the position of a digit. Total value is the digit multiplied by the value of its place. In 365,482:","bullets":["3 is in the hundred thousands place: total value 300,000","6 is in the ten thousands place: 60,000","5 is in the thousands place: 5,000","4 is in the hundreds place: 400","8 is in the tens place: 80","2 is in the ones place: 2"],"callout":"Place value is where the digit sits. Total value is how much it is worth there."}',3);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-1-1-s4','l-g5m-1-1-1','example','Worked example: rounding 36,548','{"steps":["To the nearest hundred, look at the tens digit, which is 4. It is less than 5, so round down: 36,500.","To the nearest thousand, look at the hundreds digit, which is 5. Round up: 37,000."]}',4);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-1-1-s5','l-g5m-1-1-1','explanation','Divisibility tests','{"bullets":["Divisible by 2: the last digit is 0, 2, 4, 6 or 8.","Divisible by 5: the last digit is 0 or 5.","Divisible by 10: the last digit is 0."]}',5);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-1-1-s6','l-g5m-1-1-1','activity','Digit cards','{"steps":["Write the digits 3, 8, 0, 5, 1 and 6 on six cards.","Arrange them to make the largest 6-digit number you can.","Arrange them to make the smallest 6-digit number (a number cannot begin with 0).","Say the place value of each digit in your largest number."]}',6);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-1-1-s7','l-g5m-1-1-1','practice','Check your understanding','{"qa":[{"q":"What is the total value of 7 in 472,903?","a":"70,000, because 7 is in the ten thousands place."},{"q":"Round 48,372 to the nearest thousand.","a":"48,000, because the hundreds digit 3 is less than 5."},{"q":"Is 3,450 divisible by 5? By 10?","a":"Yes to both, because it ends in 0."}]}',7);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-1-1-1-s8','l-g5m-1-1-1','reflection','Think about it','{"text":"Where do you see big numbers in daily life, like prices, distances or populations? Why does rounding make them easier to talk about?"}',8);
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5m-1-1-1','g5m-1-1-o1');
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5m-1-1-1','g5m-1-1-o2');
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5m-1-1-1','g5m-1-1-o3');
INSERT INTO lessons (id,sub_strand_id,title,estimated_minutes,status,published_at,source_id) VALUES ('l-g5m-2-1-1','g5m-2-1','Kilometres and Metres',25,'published',datetime('now'),'src-smartlearn-pilot');
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-2-1-1-s1','l-g5m-2-1-1','introduction','The walk to school','{"text":"Odhiambo walks 2 km to school and back every day. How many metres is that in one trip?"}',1);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-2-1-1-s2','l-g5m-2-1-1','outcomes','By the end of this lesson','{"bullets":["Use the kilometre for long distances","Convert between kilometres and metres","Add and subtract lengths in km and m"]}',2);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-2-1-1-s3','l-g5m-2-1-1','explanation','One kilometre','{"text":"We use kilometres (km) to measure long distances and metres (m) for shorter ones.","bullets":["1 km = 1,000 m","Kilometres to metres: multiply by 1,000.","Metres to kilometres: divide by 1,000."],"callout":"A 1 km walk is about 10 lengths of a 100 m running track."}',3);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-2-1-1-s4','l-g5m-2-1-1','example','Worked examples','{"steps":["3 km = 3 × 1,000 = 3,000 m.","4,500 m = 4 km 500 m.","Add 2 km 300 m + 1 km 800 m: 300 m + 800 m = 1,100 m = 1 km 100 m, so the total is 4 km 100 m.","Subtract 5 km 200 m − 2 km 700 m: rename 5 km 200 m as 4 km 1,200 m, then subtract to get 2 km 500 m."]}',4);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-2-1-1-s5','l-g5m-2-1-1','activity','Pace it out','{"steps":["Mark out 100 m on your school field with a tape or a rope.","Count how many steps you take to cover 100 m.","Use that to estimate how many steps make 1 km.","Compare your estimate with a friend."]}',5);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-2-1-1-s6','l-g5m-2-1-1','practice','Check your understanding','{"qa":[{"q":"Convert 6 km to metres.","a":"6,000 m."},{"q":"Write 7,250 m in km and m.","a":"7 km 250 m."},{"q":"1 km 600 m + 2 km 700 m = ?","a":"4 km 300 m."}]}',6);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-2-1-1-s7','l-g5m-2-1-1','reflection','Think about it','{"text":"Which distances in your life are best measured in kilometres? Which are better in metres?"}',7);
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5m-2-1-1','g5m-2-1-o1');
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5m-2-1-1','g5m-2-1-o2');
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5m-2-1-1','g5m-2-1-o3');
INSERT INTO lessons (id,sub_strand_id,title,estimated_minutes,status,published_at,source_id) VALUES ('l-g5m-2-2-1','g5m-2-2','Area of Rectangles and Squares',25,'published',datetime('now'),'src-smartlearn-pilot');
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-2-2-1-s1','l-g5m-2-2-1','introduction','Covering a surface','{"text":"How many 1 cm squares would you need to cover the cover of your exercise book? That count is the area of the cover."}',1);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-2-2-1-s2','l-g5m-2-2-1','outcomes','By the end of this lesson','{"bullets":["Use the square centimetre (cm²) as a unit of area","Work out the area of rectangles and squares"]}',2);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-2-2-1-s3','l-g5m-2-2-1','explanation','Counting squares','{"text":"Area is the amount of flat space a shape covers. We measure it in square centimetres (cm²). A rectangle 6 cm long and 4 cm wide holds 4 rows of 6 squares.","bullets":["Area of a rectangle = length × width","Area of a square = side × side"],"callout":"Rows times columns gives the number of squares."}',3);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-2-2-1-s4','l-g5m-2-2-1','example','Worked examples','{"steps":["Rectangle 6 cm by 4 cm: 6 × 4 = 24 cm².","Square with a side of 5 cm: 5 × 5 = 25 cm²."]}',4);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-2-2-1-s5','l-g5m-2-2-1','activity','Make a 1 cm grid','{"steps":["Draw a grid of 1 cm squares on squared paper or cut out 1 cm squares.","Cover a small rectangle, such as a matchbox lid.","Count the squares and then check with length × width."]}',5);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-2-2-1-s6','l-g5m-2-2-1','practice','Check your understanding','{"qa":[{"q":"Find the area of a rectangle 8 cm by 3 cm.","a":"8 × 3 = 24 cm²."},{"q":"Find the area of a square with a side of 7 cm.","a":"7 × 7 = 49 cm²."},{"q":"A rectangle has an area of 30 cm² and a length of 6 cm. What is its width?","a":"30 ÷ 6 = 5 cm."}]}',6);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-2-2-1-s7','l-g5m-2-2-1','reflection','Think about it','{"text":"Where would a farmer or builder need to know an area?"}',7);
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5m-2-2-1','g5m-2-2-o1');
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5m-2-2-1','g5m-2-2-o2');
INSERT INTO lessons (id,sub_strand_id,title,estimated_minutes,status,published_at,source_id) VALUES ('l-g5m-4-1-1','g5m-4-1','Tally Marks and Frequency Tables',25,'published',datetime('now'),'src-smartlearn-pilot');
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-4-1-1-s1','l-g5m-4-1-1','introduction','Favourite fruit','{"text":"Your teacher asks 20 learners to choose their favourite fruit. How can we record the answers so they are easy to count and read?"}',1);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-4-1-1-s2','l-g5m-4-1-1','outcomes','By the end of this lesson','{"bullets":["Collect data and record it with tally marks","Make a frequency table","Read and interpret a frequency table"]}',2);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-4-1-1-s3','l-g5m-4-1-1','explanation','Tally marks','{"text":"A tally mark is one stroke for each item counted. Every fifth stroke is drawn across the first four, so we can count in fives.","bullets":["A frequency table lists each choice and how many times it was chosen.","The total frequency is the number of learners asked."],"callout":"Collect, tally, count, then write the frequency."}',3);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-4-1-1-s4','l-g5m-4-1-1','example','Worked example: favourite fruit','{"steps":["Mango: |||| || = 7","Banana: |||| = 5","Orange: ||| = 3","Pawpaw: |||| = 5","Total: 7 + 5 + 3 + 5 = 20 learners."]}',4);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-4-1-1-s5','l-g5m-4-1-1','activity','Collect your own data','{"steps":["Ask 30 people at home or school a question, such as their shoe size or favourite subject.","Record each answer with a tally mark.","Count the tallies and write the frequency table.","Write two things the table tells you."]}',5);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-4-1-1-s6','l-g5m-4-1-1','practice','Check your understanding','{"qa":[{"q":"In the fruit table, how many learners chose banana or pawpaw?","a":"5 + 5 = 10 learners."},{"q":"Which fruit was the least popular?","a":"Orange, with 3 learners."},{"q":"How many learners were asked?","a":"20 learners."}]}',6);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5m-4-1-1-s7','l-g5m-4-1-1','reflection','Think about it','{"text":"Why is a table easier to read than a long list of answers?"}',7);
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5m-4-1-1','g5m-4-1-o1');
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5m-4-1-1','g5m-4-1-o2');
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5m-4-1-1','g5m-4-1-o3');
INSERT INTO lessons (id,sub_strand_id,title,estimated_minutes,status,published_at,source_id) VALUES ('l-g5s-1-1-1','g5s-1-1','Flowering Plants and Parts of a Flower',30,'published',datetime('now'),'src-smartlearn-pilot');
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-1-1-1-s1','l-g5s-1-1-1','introduction','A walk outside','{"text":"Look at the plants around your school. Some, like beans and hibiscus, make flowers. Others, like ferns and mosses, never do. How can we tell the groups apart?"}',1);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-1-1-1-s2','l-g5s-1-1-1','outcomes','By the end of this lesson','{"bullets":["Classify plants as flowering or non-flowering","Name the parts of a flower and say what each does","Explain why flowers matter in nature"]}',2);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-1-1-1-s3','l-g5s-1-1-1','explanation','Two groups of plants','{"bullets":["Flowering plants make flowers and then seeds: bean, maize, mango, sunflower.","Non-flowering plants do not make flowers: ferns and mosses."],"callout":"Follow your school''s safety rules when you touch or pick plants."}',3);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-1-1-1-s4','l-g5s-1-1-1','explanation','Parts of a flower','{"bullets":["Sepals: small green parts that protect the flower bud.","Petals: bright, scented parts that attract insects and birds.","Stamen: the male part. It makes pollen.","Pistil: the female part. The stigma catches pollen and the ovary holds the ovules.","After pollination the ovules become seeds, and the ovary grows into the fruit."]}',4);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-1-1-1-s5','l-g5s-1-1-1','activity','Observe and draw','{"steps":["With your teacher, collect a fallen hibiscus or other large flower.","Draw it and label the sepals, petals, stamens and pistil.","Write one job next to each label.","Sort five plants you see into flowering and non-flowering."]}',5);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-1-1-1-s6','l-g5s-1-1-1','practice','Check your understanding','{"qa":[{"q":"Which part of a flower attracts insects?","a":"The petals."},{"q":"Which part makes pollen?","a":"The stamen."},{"q":"Name two non-flowering plants.","a":"For example ferns and mosses."}]}',6);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-1-1-1-s7','l-g5s-1-1-1','reflection','Think about it','{"text":"What would happen to fruits and seeds if there were no flowers?"}',7);
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5s-1-1-1','g5s-1-1-o1');
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5s-1-1-1','g5s-1-1-o2');
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5s-1-1-1','g5s-1-1-o3');
INSERT INTO lessons (id,sub_strand_id,title,estimated_minutes,status,published_at,source_id) VALUES ('l-g5s-2-1-1','g5s-2-1','Separating Mixtures',30,'published',datetime('now'),'src-smartlearn-pilot');
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-2-1-1-s1','l-g5s-2-1-1','introduction','Beans and maize','{"text":"Mama mixes beans and maize for githeri, but sometimes the stones and husks end up in the sack too. How do we separate them?"}',1);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-2-1-1-s2','l-g5s-2-1-1','outcomes','By the end of this lesson','{"bullets":["Tell homogeneous and heterogeneous mixtures apart","Choose a suitable method to separate a mixture","Give uses of separating mixtures in daily life"]}',2);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-2-1-1-s3','l-g5s-2-1-1','explanation','What is a mixture?','{"text":"A mixture is two or more substances mixed but not joined together, so they can be separated again.","bullets":["Homogeneous mixture: looks the same throughout, for example sugar dissolved in tea.","Heterogeneous mixture: you can see the different parts, for example sand and water or beans and maize."]}',3);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-2-1-1-s4','l-g5s-2-1-1','explanation','Ways of separating','{"bullets":["Picking: remove large pieces, such as stones from beans.","Winnowing: wind blows light chaff away from heavy grains.","Sieving: small particles pass through holes, bigger ones stay behind.","Using a magnet: removes iron or steel pieces.","Filtering: a cloth or filter paper holds back solid bits in a liquid.","Decanting: carefully pour off the liquid from a solid that has settled.","Separating funnel: separates two liquids that do not mix, such as oil and water."]}',4);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-2-1-1-s5','l-g5s-2-1-1','activity','Separate and record','{"steps":["Mix sand, small stones and iron nails in a basin (use gloves).","Use a sieve and a magnet to separate them.","Mix soil with water, let it settle, then decant and filter.","Write which method worked best for each mixture."]}',5);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-2-1-1-s6','l-g5s-2-1-1','practice','Check your understanding','{"qa":[{"q":"Which method separates iron nails from sand?","a":"A magnet."},{"q":"Which method separates maize grain from chaff?","a":"Winnowing."},{"q":"Is sugar dissolved in tea homogeneous or heterogeneous?","a":"Homogeneous."}]}',6);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-2-1-1-s7','l-g5s-2-1-1','reflection','Think about it','{"text":"Where at home or on a farm do people separate mixtures every day?"}',7);
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5s-2-1-1','g5s-2-1-o1');
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5s-2-1-1','g5s-2-1-o2');
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5s-2-1-1','g5s-2-1-o3');
INSERT INTO lessons (id,sub_strand_id,title,estimated_minutes,status,published_at,source_id) VALUES ('l-g5s-3-1-1','g5s-3-1','Floating and Sinking',25,'published',datetime('now'),'src-smartlearn-pilot');
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-3-1-1-s1','l-g5s-3-1-1','introduction','Why does a boat float?','{"text":"A stone sinks, but a heavy ship floats. Why do some things float and others sink?"}',1);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-3-1-1-s2','l-g5s-3-1-1','outcomes','By the end of this lesson','{"bullets":["Test which materials float or sink","Identify things that affect floating and sinking","Explain how floating is useful in daily life"]}',2);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-3-1-1-s3','l-g5s-3-1-1','explanation','Material, shape and size','{"bullets":["Dry wood, cork and an empty plastic bottle float.","Stones, coins and metal keys sink.","Shape matters: a ball of plasticine sinks, but the same plasticine shaped like a boat can float because it spreads out and pushes aside more water.","Floating things are used in boats, life jackets and swimming floats."],"callout":"Never walk or swim in flood water. Floating objects can be carried away fast."}',3);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-3-1-1-s4','l-g5s-3-1-1','activity','Float or sink?','{"steps":["Fill a basin with clean water.","Predict, then test five objects, such as a cork, a stone, a coin, a leaf and a bottle top.","Make a ball of plasticine and see what happens, then shape it like a boat.","Record your results in a table."]}',4);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-3-1-1-s5','l-g5s-3-1-1','practice','Check your understanding','{"qa":[{"q":"Name two things that float and two that sink.","a":"Float: wood, cork. Sink: stone, coin."},{"q":"Why can a plasticine boat float when a plasticine ball sinks?","a":"The boat shape spreads the plasticine out and pushes aside more water."},{"q":"How is a life jacket useful?","a":"It floats and keeps a person''s head above the water."}]}',5);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-3-1-1-s6','l-g5s-3-1-1','reflection','Think about it','{"text":"How could you make a simple life saver from materials around your home?"}',6);
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5s-3-1-1','g5s-3-1-o1');
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5s-3-1-1','g5s-3-1-o2');
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5s-3-1-1','g5s-3-1-o3');
INSERT INTO lessons (id,sub_strand_id,title,estimated_minutes,status,published_at,source_id) VALUES ('l-g5s-3-2-1','g5s-3-2','How Sound Travels',25,'published',datetime('now'),'src-smartlearn-pilot');
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-3-2-1-s1','l-g5s-3-2-1','introduction','A drum on the table','{"text":"Put a few grains of rice on a drum skin and tap it. The grains jump. What is making them move?"}',1);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-3-2-1-s2','l-g5s-3-2-1','outcomes','By the end of this lesson','{"bullets":["Identify sources of sound","Show that sound travels in all directions","Describe effects of loud sound"]}',2);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-3-2-1-s3','l-g5s-3-2-1','explanation','Sound comes from vibrations','{"bullets":["Sound is made when something vibrates, such as a drum skin, a guitar string or your vocal cords.","Sound travels outwards in all directions from its source.","When sound hits a hard surface it can bounce back. This is an echo.","Very loud sound can damage hearing and disturb others."],"callout":"Keep music and headphones at a safe volume."}',3);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-3-2-1-s4','l-g5s-3-2-1','activity','Rubber band guitar','{"steps":["Stretch rubber bands of different thicknesses over an open box.","Pluck each one and listen to the sound.","Watch the band vibrate as it makes sound.","Stand in different places around a friend who is clapping. Can everyone hear it?"]}',4);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-3-2-1-s5','l-g5s-3-2-1','practice','Check your understanding','{"qa":[{"q":"What produces sound?","a":"Vibrating objects."},{"q":"What is an echo?","a":"Sound that bounces back from a hard surface."},{"q":"Give one way to reduce harm from loud sound.","a":"Turn the volume down or keep away from the noise."}]}',5);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5s-3-2-1-s6','l-g5s-3-2-1','reflection','Think about it','{"text":"What sounds around you help to keep you safe, and what sounds are too loud?"}',6);
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5s-3-2-1','g5s-3-2-o1');
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5s-3-2-1','g5s-3-2-o2');
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5s-3-2-1','g5s-3-2-o3');
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5s-3-2-1','g5s-3-2-o4');
INSERT INTO lessons (id,sub_strand_id,title,estimated_minutes,status,published_at,source_id) VALUES ('l-g5e-3-1-1','g5e-3-1','This, These, That and Those',20,'published',datetime('now'),'src-smartlearn-pilot');
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5e-3-1-1-s1','l-g5e-3-1-1','introduction','Near and far','{"text":"Hold a mango in your hand and say: This mango is sweet. Now point to a tree across the field and say: That tree is tall. What changed?"}',1);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5e-3-1-1-s2','l-g5e-3-1-1','outcomes','By the end of this lesson','{"bullets":["Identify this, these, that and those in sentences","Choose the correct word for near, far, one or many"]}',2);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5e-3-1-1-s3','l-g5e-3-1-1','explanation','Four small words','{"bullets":["this: one thing that is near","these: more than one thing that are near","that: one thing that is far","those: more than one thing that are far"],"text":"These words are called demonstrative determiners. They come before a noun and point to it."}',3);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5e-3-1-1-s4','l-g5e-3-1-1','example','Examples','{"steps":["This book is mine.","These books are mine.","That cow is grazing.","Those cows are grazing."]}',4);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5e-3-1-1-s5','l-g5e-3-1-1','activity','Point and say','{"steps":["Hold up a pencil and say a sentence with this.","Hold up two pencils and say a sentence with these.","Point to one object far away and use that.","Point to many objects far away and use those."]}',5);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5e-3-1-1-s6','l-g5e-3-1-1','practice','Check your understanding','{"qa":[{"q":"___ books in my hand are new. (near, many)","a":"These"},{"q":"Look at ___ bird over there. (far, one)","a":"that"},{"q":"___ chair here is broken. (near, one)","a":"This"}]}',6);
INSERT INTO lesson_sections (id,lesson_id,section_type,title,content_json,sort_order) VALUES ('l-g5e-3-1-1-s7','l-g5e-3-1-1','reflection','Think about it','{"text":"Why do we need different words for near and far?"}',7);
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5e-3-1-1','g5e-3-1-o1');
INSERT INTO lesson_outcomes (lesson_id,outcome_id) VALUES ('l-g5e-3-1-1','g5e-3-1-o2');
