INSERT INTO assessment_questions (id,assessment_id,question_type,prompt,points,options_json,sort_order) VALUES ('asm-g5m-frac-q1','asm-g5m-frac','mcq','Which fraction is equivalent to 1/2?',1,'[{"id":"asm-g5m-frac-q1a","label":"2/4"},{"id":"asm-g5m-frac-q1b","label":"2/3"},{"id":"asm-g5m-frac-q1c","label":"1/4"},{"id":"asm-g5m-frac-q1d","label":"3/4"}]',1);
INSERT INTO answer_keys (question_id,correct_option_id,accepted_json,explanation) VALUES ('asm-g5m-frac-q1','asm-g5m-frac-q1a',NULL,'Multiply the top and bottom of 1/2 by 2 to get 2/4.');
INSERT INTO assessment_questions (id,assessment_id,question_type,prompt,points,options_json,sort_order) VALUES ('asm-g5m-frac-q2','asm-g5m-frac','mcq','Simplify 6/8.',1,'[{"id":"asm-g5m-frac-q2a","label":"3/4"},{"id":"asm-g5m-frac-q2b","label":"2/3"},{"id":"asm-g5m-frac-q2c","label":"6/4"},{"id":"asm-g5m-frac-q2d","label":"1/2"}]',2);
INSERT INTO answer_keys (question_id,correct_option_id,accepted_json,explanation) VALUES ('asm-g5m-frac-q2','asm-g5m-frac-q2a',NULL,'Divide the top and bottom by 2.');
INSERT INTO assessment_questions (id,assessment_id,question_type,prompt,points,options_json,sort_order) VALUES ('asm-g5m-frac-q3','asm-g5m-frac','true_false','3/4 is greater than 5/8.',1,'[{"id":"asm-g5m-frac-q3t","label":"True"},{"id":"asm-g5m-frac-q3f","label":"False"}]',3);
INSERT INTO answer_keys (question_id,correct_option_id,accepted_json,explanation) VALUES ('asm-g5m-frac-q3','asm-g5m-frac-q3t',NULL,'3/4 = 6/8, and 6/8 is greater than 5/8.');
INSERT INTO assessment_questions (id,assessment_id,question_type,prompt,points,options_json,sort_order) VALUES ('asm-g5m-frac-q4','asm-g5m-frac','mcq','What is 2/7 + 3/7?',1,'[{"id":"asm-g5m-frac-q4a","label":"5/14"},{"id":"asm-g5m-frac-q4b","label":"5/7"},{"id":"asm-g5m-frac-q4c","label":"6/7"},{"id":"asm-g5m-frac-q4d","label":"1/7"}]',4);
INSERT INTO answer_keys (question_id,correct_option_id,accepted_json,explanation) VALUES ('asm-g5m-frac-q4','asm-g5m-frac-q4b',NULL,'Add the numerators and keep the denominator.');
INSERT INTO assessment_questions (id,assessment_id,question_type,prompt,points,options_json,sort_order) VALUES ('asm-g5m-frac-q5','asm-g5m-frac','short_answer','Work out 1/2 + 1/4. Write the answer as a fraction.',1,NULL,5);
INSERT INTO answer_keys (question_id,correct_option_id,accepted_json,explanation) VALUES ('asm-g5m-frac-q5',NULL,'["3/4"]','1/2 = 2/4, and 2/4 + 1/4 = 3/4.');
INSERT INTO assessments (id,title,sub_strand_id,status,approved,version,published_at) VALUES ('asm-g5m-place','Place value and rounding','g5m-1-1','published',1,1,datetime('now'));
