INSERT INTO assessment_questions (id,assessment_id,question_type,prompt,points,options_json,sort_order) VALUES ('asm-g5m-place-q1','asm-g5m-place','mcq','In 365,482, what is the place value of the digit 6?',1,'[{"id":"asm-g5m-place-q1a","label":"Thousands"},{"id":"asm-g5m-place-q1b","label":"Ten thousands"},{"id":"asm-g5m-place-q1c","label":"Hundreds"},{"id":"asm-g5m-place-q1d","label":"Hundred thousands"}]',1);
INSERT INTO answer_keys (question_id,correct_option_id,accepted_json,explanation) VALUES ('asm-g5m-place-q1','asm-g5m-place-q1b',NULL,'6 is in the ten thousands place.');
INSERT INTO assessment_questions (id,assessment_id,question_type,prompt,points,options_json,sort_order) VALUES ('asm-g5m-place-q2','asm-g5m-place','mcq','In 365,482, what is the total value of the digit 3?',1,'[{"id":"asm-g5m-place-q2a","label":"3,000"},{"id":"asm-g5m-place-q2b","label":"30,000"},{"id":"asm-g5m-place-q2c","label":"300,000"},{"id":"asm-g5m-place-q2d","label":"300"}]',2);
INSERT INTO answer_keys (question_id,correct_option_id,accepted_json,explanation) VALUES ('asm-g5m-place-q2','asm-g5m-place-q2c',NULL,'3 is in the hundred thousands place, so its value is 300,000.');
INSERT INTO assessment_questions (id,assessment_id,question_type,prompt,points,options_json,sort_order) VALUES ('asm-g5m-place-q3','asm-g5m-place','short_answer','Round 36,548 to the nearest thousand.',1,NULL,3);
INSERT INTO answer_keys (question_id,correct_option_id,accepted_json,explanation) VALUES ('asm-g5m-place-q3',NULL,'["37000", "37,000"]','The hundreds digit is 5, so round up to 37,000.');
INSERT INTO assessment_questions (id,assessment_id,question_type,prompt,points,options_json,sort_order) VALUES ('asm-g5m-place-q4','asm-g5m-place','true_false','24,000 is divisible by 5.',1,'[{"id":"asm-g5m-place-q4t","label":"True"},{"id":"asm-g5m-place-q4f","label":"False"}]',4);
INSERT INTO answer_keys (question_id,correct_option_id,accepted_json,explanation) VALUES ('asm-g5m-place-q4','asm-g5m-place-q4t',NULL,'Numbers ending in 0 are divisible by 5.');
INSERT INTO assessment_questions (id,assessment_id,question_type,prompt,points,options_json,sort_order) VALUES ('asm-g5m-place-q5','asm-g5m-place','mcq','What is the LCM of 4 and 6?',1,'[{"id":"asm-g5m-place-q5a","label":"24"},{"id":"asm-g5m-place-q5b","label":"12"},{"id":"asm-g5m-place-q5c","label":"10"},{"id":"asm-g5m-place-q5d","label":"2"}]',5);
INSERT INTO answer_keys (question_id,correct_option_id,accepted_json,explanation) VALUES ('asm-g5m-place-q5','asm-g5m-place-q5b',NULL,'Multiples of 4: 4, 8, 12. Multiples of 6: 6, 12. The first common one is 12.');
INSERT INTO assessments (id,title,sub_strand_id,status,approved,version,published_at) VALUES ('asm-g5s-plants','Flowers and plants','g5s-1-1','published',1,1,datetime('now'));
INSERT INTO assessment_outcomes (assessment_id,outcome_id) VALUES ('asm-g5s-plants','g5s-1-1-o1');
INSERT INTO assessment_outcomes (assessment_id,outcome_id) VALUES ('asm-g5s-plants','g5s-1-1-o2');
