INSERT INTO assessment_questions (id,assessment_id,question_type,prompt,points,options_json,sort_order) VALUES ('asm-g5s-plants-q1','asm-g5s-plants','mcq','Which part of a flower attracts insects?',1,'[{"id":"asm-g5s-plants-q1a","label":"Sepals"},{"id":"asm-g5s-plants-q1b","label":"Petals"},{"id":"asm-g5s-plants-q1c","label":"Stamen"},{"id":"asm-g5s-plants-q1d","label":"Ovary"}]',1);
INSERT INTO answer_keys (question_id,correct_option_id,accepted_json,explanation) VALUES ('asm-g5s-plants-q1','asm-g5s-plants-q1b',NULL,'Bright, scented petals attract insects.');
INSERT INTO assessment_questions (id,assessment_id,question_type,prompt,points,options_json,sort_order) VALUES ('asm-g5s-plants-q2','asm-g5s-plants','true_false','Ferns are flowering plants.',1,'[{"id":"asm-g5s-plants-q2t","label":"True"},{"id":"asm-g5s-plants-q2f","label":"False"}]',2);
INSERT INTO answer_keys (question_id,correct_option_id,accepted_json,explanation) VALUES ('asm-g5s-plants-q2','asm-g5s-plants-q2f',NULL,'Ferns do not make flowers.');
INSERT INTO assessment_questions (id,assessment_id,question_type,prompt,points,options_json,sort_order) VALUES ('asm-g5s-plants-q3','asm-g5s-plants','mcq','Which part of a flower makes pollen?',1,'[{"id":"asm-g5s-plants-q3a","label":"Pistil"},{"id":"asm-g5s-plants-q3b","label":"Stamen"},{"id":"asm-g5s-plants-q3c","label":"Sepal"},{"id":"asm-g5s-plants-q3d","label":"Petal"}]',3);
INSERT INTO answer_keys (question_id,correct_option_id,accepted_json,explanation) VALUES ('asm-g5s-plants-q3','asm-g5s-plants-q3b',NULL,'The stamen is the male part and makes pollen.');
INSERT INTO assessment_questions (id,assessment_id,question_type,prompt,points,options_json,sort_order) VALUES ('asm-g5s-plants-q4','asm-g5s-plants','mcq','Which part of the flower grows into the fruit?',1,'[{"id":"asm-g5s-plants-q4a","label":"Petal"},{"id":"asm-g5s-plants-q4b","label":"Sepal"},{"id":"asm-g5s-plants-q4c","label":"Ovary"},{"id":"asm-g5s-plants-q4d","label":"Stamen"}]',4);
